# 金额关键词写成英文格式（Rp 50,000 / 50,000 / 50k / 50 thousand），评分脚本据此判金额错。
def A(n):
    k = n // 1000
    g = f"{n:,}"
    out = [g, f"Rp {g}", f"{k}k", f"{k} thousand"] if n < 1_000_000 else [g, f"Rp {g}", f"{n/1e6:g} million", f"{n/1e6:g}m"]
    return out
